#!/usr/bin/env bash
# Writes config/components/postgres-migrations/configmap.yaml from
# migrations/migrate.sh and migrations/*.sql, so the Job runs exactly the
# files in migrations/. With --verify, fails if the checked-in ConfigMap
# differs instead of writing it.
set -o errexit
set -o nounset
set -o pipefail

SCRIPT_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)
OUT="${SCRIPT_ROOT}/config/components/postgres-migrations/configmap.yaml"

render() {
    cat <<'EOF'
# Generated by hack/update-migrations-configmap.sh from migrations/. Do not edit.
apiVersion: v1
kind: ConfigMap
metadata:
  name: postgres-migrations
  namespace: quota-system
  labels:
    app.kubernetes.io/name: postgres-migrations
    app.kubernetes.io/component: database
    app.kubernetes.io/part-of: quota.miloapis.com
data:
EOF
    local f
    for f in "${SCRIPT_ROOT}/migrations/migrate.sh" "${SCRIPT_ROOT}"/migrations/*.sql; do
        echo "  $(basename "${f}"): |"
        # Blank lines stay empty so the block scalar has no trailing spaces.
        sed -e 's/^\(.\)/    \1/' "${f}"
    done
}

if [[ "${1:-}" == "--verify" ]]; then
    if ! diff -u "${OUT}" <(render); then
        echo "${OUT} is out of date; run hack/update-migrations-configmap.sh" >&2
        exit 1
    fi
    exit 0
fi

render > "${OUT}"
